const file='HowToDayTrade_byRossCameron_2023_DigitalGiftCopy.pdf';
const source=(pages,printed,chapter)=>({file,pages,printed,chapter});
const check=(id,question,yes,no1,no2)=>({id,question,options:[{id:'a',text:yes[0],explanation:yes[1]},{id:'b',text:no1[0],explanation:no1[1]},{id:'c',text:no2[0],explanation:no2[1]}],answer:'a'});
// Original prose and examples. Book references concern the supplied 2023 edition, not current account rules.
export const dayLessons=[
{
id:'dt-01',title:'Day-trading expectations',objective:'Separate the work of learning a stock-trading process from promises about its results.',minutes:7,
explanation:['Day trading means opening and closing a position during the same trading day. A short holding period does not make a decision simple: you still need a reason to enter, a way to recognize failure and a plan for what happens next. This track concerns stocks; a stock chart is not automatically a reason to buy an option.','Cameron begins by challenging easy-money stories and describing substantial learning work. The book states that his results are not typical. A selected success story cannot tell you the probability of success for an average beginner. An attractive screenshot leaves out losses, costs, preparation and surrounding decisions.','Use these lessons to practice observation and decision records with fictional money. A quiz measures understanding of its explanation, not whether you can earn consistent profits or should risk savings. A useful early target is a repeatable routine: study, rehearse, review and revise.'],
definitions:[{term:'Day trade',definition:'A position opened and closed within the same trading day.'},{term:'Process goal',definition:'A behavior you can check, such as writing an exit plan before entering.'},{term:'Outcome uncertainty',definition:'A reasonable analysis can still lead to a loss.'}],
example:'Original planning example: Six study hours include two for concepts, two for simulator practice and one for record review. One hour remains for revisiting mistakes. This is not a required schedule from the book.',
mistake:'Treating exceptional profits or a perfect quiz as evidence of your future profitability.',
exercise:{question:'From six hours, after 2 hours of concepts, 2 of practice and 1 of review, how many hours remain?',answer:1,tolerance:.01,explanation:'6 - 2 - 2 - 1 = 1 hour. Review is part of the work.'},
checks:[check('dt-01-c1','Which measures a process goal?',['Whether an exit plan was written before entry.','This behavior can be checked regardless of outcome.'],['Whether every trade won.','Even planned trades can lose.'],['Whether another trader reported a big gain.','Their result does not measure your process.']),check('dt-01-c2','What do selected success stories establish about typical beginners?',['They do not establish typical outcomes.','The book explicitly warns that the author’s results are not typical.'],['All diligent readers should expect that income.','Effort does not make individual results transferable.'],['Quiz scores predict live profit.','Concept checks do not measure live execution or outcomes.']),check('dt-01-c3','What does this stock-study track teach?',['Observation and planning for stock practice.','Options require their separate curriculum and risk analysis.'],['Automatic options recommendations.','A stock setup does not determine an options order.'],['Elimination of market uncertainty.','Learning does not remove uncertainty.'])],
recap:['Practice a process you can record.','Personal stories are not typical-result evidence.','Completion is not certification for profitable real-money trading.'],
source:source([6,15,16,17,18,62,63],'pp. 1-4, 48-49; Important Notes on unnumbered PDF page 6','1: The Myth and the Reality; 3: Day Trading is a Scam!')
},
{
id:'dt-02',title:'Learning from trading experience',objective:'Use records to distinguish a repeatable behavior from an appealing story.',minutes:8,
explanation:['The author’s journey includes small gains interrupted by large losses. The transferable exercise is not to reproduce his income timeline. It is to inspect the process he describes: comparing records, identifying repeated behaviors and narrowing decisions with explicit criteria.','A useful review separates decision and outcome. “I keep adding after my planned exit” identifies something testable. “The market is against me” does not explain what to change. Record what you knew before entering so hindsight does not rewrite the reason.','Win rate alone can hide a poor balance between average gains and losses. A small sample may reveal a problem worth investigating, but does not prove a durable edge. Treat a personal story as a source of questions for practice.'],
definitions:[{term:'Trade history',definition:'A record of entries, exits, sizes and results.'},{term:'Win rate',definition:'Winning closed trades divided by all closed trades in the stated sample.'},{term:'Hindsight',definition:'Information learned after a decision that was unavailable when it was made.'}],
example:'Original example: Five practice trades gain $12 each and one loses $70. The learner won five of six, but total P/L is -$10. Review why one loss outweighed several wins.',
mistake:'Counting only winners or using later information to explain the original decision.',
exercise:{question:'Five gains of $12 and one loss of $70 give what total dollar P/L? Use a negative value for a loss.',answer:-10,tolerance:.01,explanation:'5 × $12 - $70 = -$10. High win rate alone does not describe the result.'},
checks:[check('dt-02-c1','Which journal statement is useful?',['I exited $0.20 beyond the exit planned before entry.','It records a measurable plan/action gap.'],['It was obviously going to fall.','“Obviously” may import hindsight.'],['I am a bad trader.','A self-label identifies no testable behavior.']),check('dt-02-c2','What can six practice trades establish?',['A possible issue to investigate further.','A small sample guides review without proving an edge.'],['A guaranteed strategy.','Six outcomes do not remove randomness.'],['Nothing worth recording.','Repeated process mistakes can still be visible.']),check('dt-02-c3','What is the transferable part of the journey?',['Reviewing records and using explicit criteria.','You can practice the method without claiming his outcomes.'],['Replicating his financial timeline.','Individual timelines are not typical-result evidence.'],['Increasing risk after every loss.','That does not follow from disciplined review.'])],
recap:['Keep original reason and later reflection separate.','Compare average win and loss as well as frequency.','Use biographies as questions, not promises.'],
source:source([20,30,31,35,36,40,42],'pp. 6, 16-17, 21-22, 26, 28','2: Who am I to Talk about Day Trading?')
},
{
id:'dt-03',title:'Tools, simulation and preparation',objective:'Build a deliberate practice session and recognize this app’s limits.',minutes:8,
explanation:['Chapter 5 discusses an efficient workspace and simulator use. The author describes real-time data, market depth, hotkeys and exportable history as features he wanted. These are his 2023 tool preferences, not a claim that this free app supplies a complete brokerage workstation.','PaperMoney is a smaller classroom: theoretical or manually entered prices, disclosed bid-ask fills and no live order book or real liquidity. Read price-source labels before drawing conclusions. A hypothetical fill does not establish that the same price or size was available in a live market.','Before practicing, choose the exercise, account workspace, price source and record you will keep. Make the plan visible and reduce distractions. Rehearse speed only after understanding the action: fast input cannot repair undefined risk or an accidental order.'],
definitions:[{term:'Simulator',definition:'A fictional-money system modeling selected trading features.'},{term:'Hotkey',definition:'A shortcut bound to a defined action.'},{term:'Market depth',definition:'Displayed buying and selling interest at several prices; not modeled here.'}],
example:'Original session: 20 minutes preparing and inspecting source labels, 15 rehearsing one action, then 10 reviewing the record. Total: 45 minutes.',
mistake:'Treating simplified fills as evidence of live executability.',
exercise:{question:'How many minutes total are 20 minutes of preparation, 15 of rehearsal and 10 of review?',answer:45,tolerance:.01,explanation:'20 + 15 + 10 = 45 minutes, including review.'},
checks:[check('dt-03-c1','What should you first check about a practice price?',['Whether it is theoretical or a dated manual snapshot.','Source and timestamp determine what it means.'],['Which number looks most profitable.','Attractiveness does not establish freshness.'],['Whether it is green.','Color does not prove a live quote.']),check('dt-03-c2','Which describes this app?',['Educational fills without real liquidity simulation.','It needs no live order book or brokerage connection.'],['Every tool in Chapter 5 is reproduced.','This is deliberately a smaller environment.'],['The displayed ask is guaranteed in real trading.','Live prices and size may change.']),check('dt-03-c3','Why can a simpler workspace help?',['It reduces irrelevant information while keeping the plan accessible.','More screens can create overload.'],['It eliminates risk.','Organization does not remove uncertainty.'],['It replaces a plan.','Tools support rather than replace a plan.'])],
recap:['Know price source and timestamp.','Practice deliberate actions before speed.','Record simulator assumptions beside results.'],
source:source([72,73,74,75,76,77],'pp. 58-63','5: The Gear You’ll Need')
},
{
id:'dt-04',title:'Shares, float and short-selling basics',objective:'Distinguish ownership, tradable supply and a short position’s direction.',minutes:9,
explanation:['A company can raise money by borrowing or selling ownership interests. A common share represents ownership; a loan creates a debt obligation. After an initial sale, shares can trade between investors. Prices change as buying and selling interest interact.','Outstanding shares and float are different counts. Outstanding shares include issued shares held by shareholders; float is the portion generally available for public trading. Neither tells you exactly how many holders will sell at a particular moment. Low float can contribute to sharp moves when demand changes, but guarantees no direction.','A conventional short seller borrows shares, sells them and later buys shares to return. A lower repurchase price helps; a higher one hurts. Short-stock loss can theoretically grow without a fixed upper bound. These are conceptual mechanics, not current-rule or account-eligibility advice. This simulator does not add naked stock shorting.'],
definitions:[{term:'Equity financing',definition:'Raising capital by selling ownership.'},{term:'Debt financing',definition:'Raising capital through borrowing repayable under its terms.'},{term:'Float',definition:'Shares generally available for public trading.'},{term:'Short sale',definition:'Selling shares not owned, generally borrowed for delivery, with an obligation to replace them.'}],
example:'Original example, ignoring costs: Sell 50 hypothetical borrowed shares at $8, then buy at $10. The difference is a $2 loss per share, or $100. Initial proceeds were not profit.',
mistake:'Confusing float with volume or treating short-sale proceeds as risk-free income.',
exercise:{question:'For a hypothetical 50-share short at $8, covered at $10, what is the positive dollar loss before costs?',answer:100,tolerance:.01,explanation:'($10 - $8) × 50 = $100. Rising prices hurt a short.'},
checks:[check('dt-04-c1','Which measures trading activity during a period?',['Volume.','It counts shares traded during the interval.'],['Float.','Float describes generally tradable supply.'],['Debt financing.','Financing describes raising capital.']),check('dt-04-c2','A short is repurchased higher. What happened before costs?',['It lost money.','Replacing shares cost more than the sale produced.'],['The original proceeds became pure profit.','The replacement obligation remained.'],['Loss is always capped at sale price.','A stock has no fixed theoretical maximum price.']),check('dt-04-c3','Does low float guarantee a rise?',['No; it supplies context, not certainty.','Demand and willingness to sell matter.'],['Yes, nobody can sell.','Tradable shares can be sold.'],['Yes, if a flag is visible.','A shape does not remove uncertainty.'])],
recap:['Float, outstanding shares and volume differ.','Short-stock risk differs from fully paid long-stock risk.','No eligibility advice or naked shorting feature is implied.'],
source:source([78,79,80,81,82,83,84,85,86,87,88,89,90],'pp. 64-76','6: Stock Market Basics'),
supplementalSources:[{title:'SEC: short-sale mechanics and risk',url:'https://www.sec.gov/investor/pubs/regsho.htm'}]
},

{
id:'dt-05',title:'Discipline, losses and FOMO',objective:'Compare an emotional reason for a trade with a plan made before pressure.',minutes:8,
explanation:['The book treats emotions as central to trading. FOMO is fear of missing out: attention shifts from decision quality to the discomfort of watching someone else appear to profit. Trying to repair a loss immediately can lead to chasing, increasing size or abandoning a planned exit.','Feeling an emotion is not the same as acting on it. Pause and reread entry reasoning, invalidation and loss limit. If you cannot explain these without referring to someone else’s profit, you may not have a plan. Waiting or skipping can be a valid analysis result under stated conditions.','Accepting a planned loss does not make every loss acceptable. Separate an ordinary losing outcome that followed the plan from a process violation such as widening a stop simply to avoid closing red. Review both. Fictional money cannot reproduce every emotional aspect of risking real funds.'],
definitions:[{term:'FOMO',definition:'Fear of missing out that pressures someone to act without a complete plan.'},{term:'Chasing',definition:'Entering away from a planned area after a move without reassessing risk.'},{term:'Invalidation',definition:'A condition under which the idea no longer fits its stated plan.'}],
example:'Original example: A practice plan caps the day’s loss at $90. Closed losses total $70 and a new idea carries $30 planned risk. Only $20 remains; the full proposed risk does not fit.',
mistake:'Treating a missed opportunity or earlier loss as a command to take the next trade.',
exercise:{question:'From the stated $90 practice loss budget, after $70 closed losses, how many dollars remain?',answer:20,tolerance:.01,explanation:'$90 - $70 = $20. The new $30 planned risk exceeds the remainder.'},
checks:[check('dt-05-c1','Which statement is most clearly FOMO-driven?',['Others made money and I feel left behind, so I must buy.','It describes comparison pressure rather than a complete plan.'],['I identified a trigger and invalidation point.','Those are plan components, though the outcome remains uncertain.'],['I skipped an idea exceeding my limit.','That respects a stated boundary.']),check('dt-05-c2','A reasonable setup loses while the plan is followed. What next?',['Record and review it without treating one result as proof.','Outcome and process need separate evaluation.'],['Double the next trade to recover.','A loss does not justify a larger next risk.'],['Delete the loss.','That hides evidence needed for honest review.']),check('dt-05-c3','What fits the example’s limits?',['Skip or revise before entry to fit the remaining budget.','The full $30 risk exceeds the remaining $20.'],['Take $30 risk because the chart is strong.','Confidence does not change the boundary.'],['Raise the limit for this trade.','That replaces the preplanned limit under pressure.'])],
recap:['Name the emotion before acting.','A missed move is not a command to chase.','Review plan adherence separately from profit.'],
source:source([92,94,95,96,97,98,99,111,112,137,138],'pp. 78, 80-85, 97-98, 123-124','7: The Battle That Will Happen Between Your Ears; 8: Risk and Fear in Trading; 10: Finding the Right Stocks to Trade')
},
{
id:'dt-06',title:'Planned risk, reward and drawdowns',objective:'Calculate reward:risk and explain why win rate alone cannot describe performance.',minutes:10,
explanation:['Before a hypothetical long-stock trade, define entry, planned stop or invalidation, target and share count. Planned risk per share is entry minus stop; potential reward is target minus entry. These are planning quantities: actual fills can be worse and a target may never trade. This lesson does not promise that a stop caps a live loss.','The book calls the comparison a profit/loss ratio. This track explicitly writes reward:risk: 2:1 means two dollars of potential reward per dollar of planned downside. Cameron describes 2:1 as his preference, not a universal law or guarantee of an attainable target.','Win rate and average win/loss size work together. If wins gain $100 and losses lose $50, exactly one-third winners is theoretical break-even before costs; positive average requires more. Costs and worse fills raise the requirement. A drawdown is a decline from an account peak. Loss limits and size constrain planned damage, not all possible loss.'],
definitions:[{term:'Reward:risk',definition:'Potential gain compared with planned loss, reward written first here.'},{term:'Position size',definition:'How many shares or units are held; it scales exposure.'},{term:'Drawdown',definition:'An account-equity decline from a stated previous peak.'}],
example:'Original example: entry $10, planned stop $9, target $12, 50 shares. Planned downside is $50, target upside $100, reward:risk 2:1. The target is a scenario, not a forecast.',
mistake:'Calling a 2:1 plan safe or counting a hoped-for target as profit.',
exercise:{question:'For entry $10, planned stop $9 and 50 shares, what is planned dollar downside, ignoring gaps and costs?',answer:50,tolerance:.01,explanation:'($10 - $9) × 50 = $50. Real execution can differ.'},
diagram:{kind:'risk',entry:10,stop:9,target:12,caption:'Original hypothetical long-stock plan; no historical data.'},
checks:[check('dt-06-c1','What does reward:risk 2:1 mean here?',['Potential gain is twice planned downside.','Reward is written first.'],['Loss is twice potential gain.','That reverses the order.'],['The trade wins twice in three tries.','This ratio compares amounts, not frequency.']),check('dt-06-c2','What belongs beside win rate?',['Average win, average loss and costs.','Outcome sizes determine whether frequency becomes net gain.'],['Only the biggest winner.','A selected extreme omits the sample.'],['Only the number of green candles.','That is not a substitute for result statistics.']),check('dt-06-c3','A $1,000 peak falls to $900. What is this?',['A $100 or 10% drawdown.','It compares equity with the prior peak.'],['Proof the next trade wins.','No recovery is required on the next trade.'],['A reason to double size.','Loss does not improve the next opportunity.'])],
recap:['Write ratio order explicitly.','Dollar risk depends on price distance and size.','Targets and stops do not guarantee execution.'],
source:source([100,101,102,103,104,109,110,111,118,119,120,121],'pp. 86-90, 95-97, 104-107','8: Risk and Fear in Trading'),practiceTopic:'risk'
},
{
id:'dt-07',title:'Candlestick foundations',objective:'Read OHLC without confusing an interval with an entire session.',minutes:8,
explanation:['A candlestick summarizes an interval with open, high, low and close. The body spans open to close; thin wicks or shadows extend to high and low. Color commonly distinguishes a close above open from one below, but conventions vary, so use values as well as color.','A one-minute candle summarizes one minute; a five-minute candle summarizes five. Neither records each transaction in order. Identical OHLC values can conceal different paths inside the interval. An unfinished candle can change shape before its interval closes.','Chapter 9 starts at physical PDF page 126, printed page 112. Its diagrams introduce candle anatomy. The illustration here uses synthetic original prices. State the observation first: close above open, long upper wick or interval unfinished. A color alone is not a forecast.'],
definitions:[{term:'Open',definition:'The first recorded price of an interval.'},{term:'Close',definition:'The last price of a completed interval; it changes while the interval is unfinished.'},{term:'Body',definition:'The span between open and close.'},{term:'Wick',definition:'The thin extension from body to high or low.'},{term:'Timeframe',definition:'The duration summarized by each candle.'}],
example:'Synthetic one-minute candle: open $10.00, high $10.50, low $9.90, close $10.30. Body $0.30; full range $0.60; upper wick $0.20; lower wick $0.10.',
mistake:'Using the body top as high when a wick extends farther, or treating an unfinished candle as final.',
exercise:{question:'For open $10.00 and close $10.30, what is body size in dollars per share?',answer:.30,tolerance:.01,explanation:'|$10.30 - $10.00| = $0.30. The full high-to-low range is different.'},
diagram:{kind:'candle',open:10,high:10.5,low:9.9,close:10.3,timeframe:'1 minute',caption:'Synthetic one-minute candle; original illustrative prices.'},
checks:[check('dt-07-c1','Where is the high when an upper wick exists?',['At the wick’s top.','That is the interval’s highest recorded price.'],['Always at the body top.','The body ends at open or close, potentially below high.'],['At the preceding close.','Another candle does not determine this interval’s high.']),check('dt-07-c2','What does a five-minute candle summarize?',['One five-minute interval.','The timeframe defines the period.'],['Every transaction’s exact sequence.','OHLC does not preserve transaction order.'],['The whole trading day.','That would be a daily candle.']),check('dt-07-c3','What matters about an unfinished candle?',['Its close and shape can change.','New trades can update close and extremes.'],['Its shape cannot change.','The interval is unfinished.'],['It reveals the next direction.','Aggregation does not reveal future prices.'])],
recap:['Locate all four prices before labeling.','Body differs from full range.','State timeframe and completion status.'],
source:source([126,127,128],'pp. 112-114','9: Introduction to Candlesticks'),practiceTopic:'candlesticks'
},
{
id:'dt-08',title:'Candlestick interpretation in context',objective:'Describe shape without treating it as a certain reversal.',minutes:9,
explanation:['A doji has open and close near one another. The same shape after a strong move and in a quiet range has different context. A long lower wick means price visited lower levels then finished above the low; a long upper wick means a visit higher and a finish below high. Neither guarantees the next candle.','The book covers dojis, topping and bottoming tails, hammer-type candles and long bodies. A large body shows strong open-to-close movement, not necessarily a good entry after an extended advance. Consider preceding movement, nearby levels, timeframe and later evidence rather than treating a silhouette as certainty.','Terminology note: physical PDF page 131 uses inverted hammer in an uptrend context. Conventional references usually call a small-body, long-upper-wick candle after an advance a shooting star; inverted hammer is discussed after a decline. This track states shape and context explicitly. StockCharts ChartSchool provides supplemental naming clarification, not a reversal guarantee.'],
definitions:[{term:'Doji',definition:'Open and close very near each other relative to the candle’s full range.'},{term:'Hammer-type shape',definition:'A small body and long lower wick; interpretation depends on context.'},{term:'Shooting star',definition:'A conventional label for a small-body, long-upper-wick candle after an advance.'},{term:'Confirmation',definition:'Additional observable evidence required by a stated interpretation.'}],
example:'Synthetic candle: open $10.00, close $10.02, high $10.60, low $9.60. Its $0.02 body is 2% of the $1.00 range. That describes a near-open close, not what happens next.',
mistake:'Treating a candle name as a complete strategy or certain prediction.',
exercise:{question:'A $0.02 body in a $1.00 full range is what percentage of the range?',answer:2,tolerance:.01,explanation:'$0.02 ÷ $1.00 × 100 = 2%. It measures shape, not future direction.'},
diagram:{kind:'candle',open:10,high:10.6,low:9.6,close:10.02,timeframe:'1 minute',caption:'Synthetic near-open-close candle; no later outcome supplied.'},
checks:[check('dt-08-c1','What does a long upper wick establish?',['Price traded above the body and finished below the interval high.','That is the observable summary.'],['The next candle must fall.','This candle cannot disclose future prices.'],['No buyers participated.','A wick cannot prove absence of buyers.']),check('dt-08-c2','Why consider the preceding trend?',['Similar shapes can differ in interpretation after a rise, decline or range.','Context helps avoid indisputable-pattern claims.'],['It guarantees a prediction.','Context informs judgment without certainty.'],['It removes timeframe concerns.','The interval still matters.']),check('dt-08-c3','How is ambiguous naming handled here?',['Describe shape and context, then explain the alternative label.','The difference is explicit, not silently changed.'],['Claim all references use the same names.','That hides the actual difference.'],['Call every upper wick a short entry.','That is an unsupported discretionary instruction.'])],
recap:['Describe evidence before naming.','Possible reversal differs from confirmed trigger.','Ask what would weaken the interpretation.'],
source:source([128,129,130,131,132,133],'pp. 114-119','9: Introduction to Candlesticks'),practiceTopic:'candlesticks',
supplementalSources:[{title:'StockCharts ChartSchool: candle terminology',url:'https://chartschool.stockcharts.com/table-of-contents/chart-analysis/candlestick-charts/introduction-to-candlesticks'}]
},

{
id:'dt-09',title:'Stock selection is more than a pattern',objective:'Explain the author’s framework without treating preferences as universal requirements.',minutes:10,
explanation:['Cameron argues that stock selection matters alongside chart shape. His momentum approach seeks a stock already attracting attention, not merely an interesting shape. Chapter 10 discusses current volatility, fear and greed, supply/demand imbalance, relative volume and a history of strong moves. This is the book’s framework, not a prediction system validated by this app.','The 2023 guardrail list summarizes his scanning preferences: over 10% versus the previous close, relative volume at least 2, prices generally $2-$10 and not over $20, a current catalyst and preferably float of 20 million shares or fewer. Chapter 10 also discusses $2-$20 stocks and exceptions. These are attributed author preferences, not universal thresholds or promises.','Relative volume compares activity with a specified baseline. Periods must be comparable; full-day volume and an early intraday total can mislead. A catalyst draws attention but guarantees no continuation. A familiar former runner may still distract from today’s stronger candidate. Screening context and chart evidence must be examined together.'],
definitions:[{term:'Catalyst',definition:'Information or an event that may change interest in a stock.'},{term:'Relative volume',definition:'Observed volume divided by a stated comparable usual-volume baseline.'},{term:'Former runner',definition:'The author’s term for a stock remembered for a prior strong move.'},{term:'Momentum',definition:'Strong current price movement that can stall or reverse.'}],
example:'Original full-day comparison: Synthetic stock A trades 600,000 shares against a 200,000-share daily average, so relative volume is 3. Stock B has a larger absolute total, but without its baseline you cannot rank relative activity. Neither is a recommendation.',
mistake:'Using one screening match as sufficient reason to trade or translating a stock screen directly into an options order.',
exercise:{question:'For the supplied comparable full-day values, 600,000 ÷ 200,000 is what relative-volume multiple?',answer:3,tolerance:.01,explanation:'Observed activity is three times the supplied baseline: 3.0.'},
checks:[check('dt-09-c1','How should the book’s price-screen numbers be presented?',['As the author’s stated 2023 preferences with context and exceptions.','They describe an approach, not universal rules.'],['As legal requirements.','The preferences are not market regulations.'],['As guarantees of profitable breakouts.','A screen does not establish future prices.']),check('dt-09-c2','What supports a meaningful relative-volume calculation?',['Observed volume and a stated comparable baseline.','Numerator, denominator and periods must be known.'],['Any two impressive volume values.','Different periods or baselines can mislead.'],['Float divided by ask price.','That is not a volume comparison.']),check('dt-09-c3','Why may a former runner distract?',['A past move does not establish strong conditions today.','Current volume and context still matter.'],['A former runner must repeat its prior move.','History does not compel a repeat.'],['All familiar symbols are always unsuitable.','The label alone neither qualifies nor disqualifies today’s setup.'])],
recap:['Attribute screening thresholds to their author and date.','Compare like periods and baselines.','A screen or chart alone is not a complete plan.'],
source:source([36,37,38,134,135,136,137,138,139,140,141,142,143,202,203],'pp. 22-24, 120-129, 188-189','2: Who am I to Talk about Day Trading?; 10: Finding the Right Stocks to Trade; 16: List of Guardrails'),practiceTopic:'volume'
},
{
id:'dt-10',title:'Practice, journal and improve',objective:'Build a review loop distinguishing results from rule-following.',minutes:9,
explanation:['Chapter 11 emphasizes knowledge, simulator practice, journals and metrics. Cameron describes a personal progression and historical guardrails that limit activity while learning. This track does not convert his timetable or green-week milestones into permission to risk real money.','A useful loop has four parts: plan practice, act within the plan, record what happened, then choose one change to test. Record entry reasoning before the outcome. Later add actual entry/exit, planned versus actual risk, emotions and a screenshot or neutral description. Review groups of trades rather than selected memorable winners.','Track both process and outcomes. A profitable practice trade may violate a plan; a losing one may follow it. Examine win rate, average win/loss, drawdown and adherence together. Simulator results do not reproduce live liquidity or emotions, so a green week or completed quiz cannot certify real-money profitability.'],
definitions:[{term:'Plan adherence',definition:'Whether the actual decision followed rules recorded before the outcome.'},{term:'Review loop',definition:'Planning, practicing, recording and choosing a specific revision.'},{term:'Sample',definition:'The stated group of trades used in a calculation.'}],
example:'Original review: Eight closed practice trades contain five winners and three losers, giving 62.5% win rate. If six followed the plan, adherence is 75%. These measure different things, not a combined readiness score.',
mistake:'Rewriting the original reason after seeing the result so the record always appears correct.',
exercise:{question:'Five winning trades out of eight closed trades give what win rate in percent?',answer:62.5,tolerance:.01,explanation:'5 ÷ 8 × 100 = 62.5%. This does not describe gain/loss sizes or prove future results.'},
checks:[check('dt-10-c1','When should the original entry reason be recorded?',['Before the outcome, then supplemented by a later reflection.','This preserves what was available at decision time.'],['Only after winning.','That omits losses and selects favorable outcomes.'],['After rewriting it to fit the result.','That destroys the plan/hindsight distinction.']),check('dt-10-c2','A winning trade broke its risk limit. How is it reviewed?',['Profitable outcome with a process violation.','A favorable result does not erase the violation.'],['Proof the limit should never apply.','One outcome cannot establish that conclusion.'],['Automatically better than every planned loss.','Process and outcome are separate dimensions.']),check('dt-10-c3','What does a simulator milestone supply?',['A record to analyze with simulator limitations still present.','Practice evidence is not profitability certification.'],['Proof real trading will feel identical.','Real funds can change emotions and execution.'],['A guarantee of the next month’s results.','A sample cannot guarantee future conditions.'])],
recap:['Preserve original reasoning.','Review both adherence and results.','Select one specific process improvement to test.'],
source:source([144,145,146,147,148,150,151,152,153,154,155,156,157],'pp. 130-134, 136-143','11: Getting Better and Better')
},
{
id:'dt-11',title:'Trader case studies: Graham and Martin',objective:'Extract process lessons from interviews without generalizing their outcomes.',minutes:9,
explanation:['The Graham interview describes repeated learning, returning to basics and adapting expectations. The Martin interview describes substantial simulator time, emotional discipline, learning from losses and reviewing feedback. The book changes their names for privacy and explicitly states their results are not typical. Keep their biographies and financial achievements separate from practical lessons.','A useful question is “Which behavior can I observe in my own practice?” rather than “When will I achieve that result?” Graham’s discussion of position size and confidence illustrates how more shares increase emotional exposure. Martin’s discussion of desperation is a reminder that wanting a win is not evidence for a trade.','Their experiences do not set a universal simulator timetable or prove that the same strategy suits every reader. You can test consistent size, record plan adherence and review losses without treating a selected interview as a success-rate study. Personal context, execution and market conditions differ.'],
definitions:[{term:'Case study',definition:'An individual experience examined for insight, not a representative statistical sample.'},{term:'Exposure',definition:'How much a position’s value can change as prices move.'},{term:'Desperation trading',definition:'Acting from a need to obtain a win rather than a completed plan.'}],
example:'Original size example: A $0.10 adverse move on 100 shares is $10 before costs; on 1,000 shares it is $100. The chart is identical, but dollar and emotional exposure are different. This is not an interviewee’s historical trade.',
mistake:'Using a selected trader’s outcome or simulator duration as a forecast of your own.',
exercise:{question:'On the original 1,000-share example, a $0.10 adverse move represents how many dollars before costs?',answer:100,tolerance:.01,explanation:'1,000 × $0.10 = $100. Ten times the shares makes ten times this price-move exposure.'},
checks:[check('dt-11-c1','What is a defensible process lesson from Graham’s discussion?',['Review expectations and return to basics when conditions no longer fit.','This is a process observation, not a claim about typical results.'],['Every learner should expect his income.','The source explicitly warns that results are not typical.'],['A previously winning pattern must work today.','Conditions can change.']),check('dt-11-c2','What follows from Martin’s discussion of desperation?',['Recognize the state and reread the plan before adding risk.','An emotional need for a win is not a setup.'],['Increase size to recover confidence instantly.','More risk does not improve evidence.'],['Disciplined traders never lose.','The interview discusses learning from losses.']),check('dt-11-c3','Why not treat the interviews as typical-result evidence?',['They are selected individual experiences with explicit typicality warnings.','They cannot establish general success probabilities.'],['Privacy names make every process observation useless.','You can still cautiously examine a described process.'],['Readers all have identical circumstances.','Finances, behavior and conditions differ.'])],
recap:['Extract a behavior, not an earnings promise.','Size changes exposure without changing the chart.','Selected interviews do not describe typical outcomes.'],
source:source([158,162,165,168,170,175,177,181,183,184,185,187],'pp. 144, 148, 151, 154, 156, 161, 163, 167, 169-171, 173','12: Interview with Graham; 13: Interview with Martin')
},
{
id:'dt-12',title:'Guardrails and a final process review',objective:'Use an original checklist without claiming real-money certification.',minutes:10,
explanation:['The book collects guardrails about stock selection, practice, planned risk, loss limits, position size and journals. They describe the author’s approach. A guardrail matters only when it constrains an actual decision before pressure arrives; moving it because a trade feels uncomfortable defeats that purpose.','Original checklist inspired by these themes: identify source and timeframe; separate observations from assumptions; describe setup separately from trigger; calculate dollar risk against chosen limits; write invalidation; choose enter, wait or skip under the plan; record and review the action. This is a new teaching checklist, not a verbatim Cameron list or an instruction to make a discretionary trade.','Unclear evidence can justify waiting or skipping. A chart name compels no entry, and a favorable later move does not make an unplanned action sound. Finishing the track demonstrates practice with its concepts, not profitable real-money readiness. Keep options learning separate because stock-chart analysis does not account for all options risks.'],
definitions:[{term:'Guardrail',definition:'A precommitted behavior boundary, such as a loss or size limit.'},{term:'Setup',definition:'Conditions making an idea worth watching.'},{term:'Trigger',definition:'An observable event required by a stated plan before acting.'},{term:'Loss budget',definition:'Maximum planned loss allowed for a stated exercise or session.'}],
example:'Original checklist: A fictional session has a chosen $100 loss budget. Closed trades lost $25 and $35. $40 remains. A proposed $50-risk idea does not fit even if the chart looks attractive.',
mistake:'Treating checklist completion as a guarantee or a possible setup as a confirmed trigger.',
exercise:{question:'From a $100 practice loss budget, after losses of $25 and $35, how many dollars remain?',answer:40,tolerance:.01,explanation:'$100 - $25 - $35 = $40. A proposed $50 risk exceeds that boundary.'},
checks:[check('dt-12-c1','A setup exists but the plan’s required trigger has not occurred. What fits?',['Wait for the event or skip.','The setup alone does not satisfy this explicit plan.'],['Enter because it has a pattern name.','A label does not replace the required event.'],['Assume later candles must confirm it.','Later information is unavailable at decision time.']),check('dt-12-c2','What is this lesson’s original checklist for?',['Organizing observation, boundaries and review.','It translates source themes into a new learning workflow.'],['Repeating exact trade commands copied from the book.','The checklist is an original teaching aid.'],['Removing every possibility of loss.','It cannot remove market or execution uncertainty.']),check('dt-12-c3','What can passing the final checks establish?',['Understanding of the tested concepts, with limitations still present.','A local quiz is educational assessment, not profitability or eligibility certification.'],['Proven readiness for profitable real trading.','A quiz cannot establish this.'],['Every stock setup now justifies an option.','Options have additional risks and a separate curriculum.'])],
recap:['Separate source, setup, trigger and invalidation.','Calculate size and remaining risk before acting.','Record enter, wait or skip and review without hindsight.','Completion is not real-money profitability certification.'],
source:source([202,203,144,146,147,154,155],'pp. 188-189, 130, 132-133, 140-141','16: List of Guardrails; 11: Getting Better and Better'),practiceTopic:'risk'
}
];

export const glossary=[
['Ask','The lowest displayed offer price; actual execution and available size may differ.','dt-04'],
['Bid','The highest displayed buying price; it does not guarantee available size.','dt-04'],
['Body','The candlestick span between its open and close.','dt-07'],
['Catalyst','Information or an event that can change attention or demand for a stock.','dt-09'],
['Chasing','Entering after price has left a planned area without reassessing the changed risk.','dt-05'],
['Close','The last price in a completed interval; its current value changes while the candle is open.','dt-07'],
['Confirmation','Additional observable evidence required by a stated interpretation or plan.','dt-08'],
['Day trade','A position opened and closed during the same trading day.','dt-01'],
['Doji','A candle with open and close near each other relative to its full range.','dt-08'],
['Drawdown','An equity decline measured from a stated previous peak.','dt-06'],
['Equity financing','Raising capital by selling an ownership interest.','dt-04'],
['Float','Shares generally available for public trading, distinct from total outstanding shares and volume.','dt-04'],
['FOMO','Fear of missing out that can pressure someone to act without a complete plan.','dt-05'],
['Former runner','A stock remembered for a previous strong move in the author’s framework.','dt-09'],
['Guardrail','A precommitted boundary intended to constrain behavior under pressure.','dt-12'],
['High','The highest recorded price in an interval.','dt-07'],
['Hotkey','A keyboard shortcut bound to a defined action.','dt-03'],
['Invalidation','A condition under which an idea no longer meets its plan.','dt-05'],
['Low','The lowest recorded price in an interval.','dt-07'],
['Momentum','Strong current price movement, which can stall or reverse.','dt-09'],
['Open','The first recorded price in an interval.','dt-07'],
['Plan adherence','Whether an action matched rules recorded before its result was known.','dt-10'],
['Position size','Number of shares or units held, scaling exposure to price changes.','dt-06'],
['Relative volume','Observed activity divided by a stated comparable usual-volume baseline.','dt-09'],
['Reward:risk','Potential gain compared with planned downside, with reward written first here.','dt-06'],
['Setup','Conditions making an idea worth watching, separate from a required trigger.','dt-12'],
['Shares outstanding','Issued shares held by shareholders, including those not generally publicly tradable.','dt-04'],
['Short sale','Selling shares not owned, generally borrowed for delivery, with an obligation to replace them.','dt-04'],
['Simulator','A fictional-money environment modeling selected trading features with stated limits.','dt-03'],
['Slippage','The difference between expected execution price and actual fill price.','dt-03'],
['Timeframe','The interval duration summarized by each candle.','dt-07'],
['Trigger','An observable event required by a stated plan before acting.','dt-12'],
['Volume','Shares traded during a specified interval, not necessarily unique shares.','dt-09'],
['Wick','The thin extension between a candle’s body and high or low; also called shadow or tail.','dt-07'],
['Win rate','Winning closed trades divided by all closed trades in a stated sample.','dt-10']
].map(([term,definition,lessonId])=>({term,definition,lessonId,source:dayLessons.find(l=>l.id===lessonId).source,note:'Original learner definition; linked lesson supplies the source context.'}));

